for(const v of DATA)for(const group of [v,...v.countries])group.series=group.series.map(row=>Object.fromEntries(FIELDS.map((key,i)=>[key,row[i]])));
const nf=new Intl.NumberFormat('de-DE',{maximumFractionDigits:1}),f=x=>nf.format(Math.abs(x)<.05?0:x),pct=x=>(x>0?'+':'')+f(x)+' %';
const defs={startingPct:{name:'Stärke der Standardstartformation',unit:'%',fmt:pct,note:'Relative Veränderung gegenüber dem identischen Anfangskader. Messung vor den Karriereenden.'},qualityPct:{name:'Stärke des gesamten Kaders',unit:'%',fmt:pct,note:'Relative Veränderung gegenüber dem Anfangskader; Messung nach den Karriereenden.'},openingPlayers:{name:'Spieler zu Saisonbeginn',unit:'Spieler',fmt:f,note:'Durchschnitt je KI-Verein nach der Reparatur des Kaders. Alle eröffneten Kader sind spielbar.'},closingPlayers:{name:'Spieler nach Saisonabschluss',unit:'Spieler',fmt:f,note:'Durchschnitt je KI-Verein nach den Karriereenden. Ergänzungen folgen zum nächsten Saisonstart.'},expenses:{name:'Jahresausgaben je Verein',unit:'Credits',fmt:f,note:'Gehälter, Förderung, Übernahmeentschädigungen und Transferausgaben; Bruttoausgaben ohne Verrechnung der Einnahmen.'},youthFunding:{name:'Jugendbudget je Verein',unit:'Credits',fmt:f,note:'Tatsächlich bezahlte Jahresförderung; durchschnittlich über die Vereine, keine zusätzliche auswählbare Stufe.'},generated:{name:'Neue Kandidaten',unit:'Spieler',fmt:f,note:'Weltsumme beziehungsweise Summe im gewählten Land; gemittelt über drei Seeds. Erste Y0-Pools ausgeschlossen.'},promoted:{name:'Übernommene Jugendliche',unit:'Spieler',fmt:f,note:'Weltsumme beziehungsweise Summe im gewählten Land; auch ältere Pooljahrgänge. Keine direkte Aufnahmequote des neuen Jahrgangs.'}};
