document.querySelector('#summary tbody').innerHTML=fields.map(([label,key,fmt])=>'<tr><td>'+label+'</td>'+DATA.map(v=>'<td>'+fmt(key?v.series.at(-1)[key]:v)+'</td>').join('')+'</tr>').join('');
